from fastapi.sse import ServerSentEvent
from pydantic import ValidationError

def test_sse_validation():
    # Valid event
    try:
        ServerSentEvent(event="test_event", id="test_id", data="test_data")
        print("Valid event passed")
    except ValidationError as e:
        print(f"Valid event failed: {e}")

    # Invalid event: newline in event
    try:
        ServerSentEvent(event="test\nevent", id="test_id", data="test_data")
        print("Invalid event (newline in event) passed - FAIL")
    except ValidationError as e:
        print(f"Invalid event (newline in event) caught: {e}")

    # Invalid event: newline in id
    try:
        ServerSentEvent(event="test_event", id="test\nid", data="test_data")
        print("Invalid event (newline in id) passed - FAIL")
    except ValidationError as e:
        print(f"Invalid event (newline in id) caught: {e}")

    # Invalid event: null in id
    try:
        ServerSentEvent(event="test_event", id="test\0id", data="test_data")
        print("Invalid event (null in id) passed - FAIL")
    except ValidationError as e:
        print(f"Invalid event (null in id) caught: {e}")

    # Invalid event: carriage return in event
    try:
        ServerSentEvent(event="test\revent", id="test_id", data="test_data")
        print("Invalid event (carriage return in event) passed - FAIL")
    except ValidationError as e:
        print(f"Invalid event (carriage return in event) caught: {e}")

if __name__ == "__main__":
    test_sse_validation()
EOF
